//! Typed 128-bit identifiers (UUID v4) for accounts, vaults, projects, items,
//! attachments and identities.
//!
//! IDs are generated by clients (they are part of the AAD before anything is
//! uploaded). On the wire and inside AAD they are the 16 raw UUID bytes; in
//! text they use the canonical hyphenated form.

use std::fmt;
use std::str::FromStr;

use thiserror::Error;
use uuid::Uuid;

use crate::crypto::random;

/// Error returned when parsing an ID from text.
#[derive(Debug, Error, Clone, PartialEq, Eq)]
#[error("invalid ID: expected a canonical hyphenated UUID")]
pub struct IdParseError;

/// Returns `true` if `s` has the canonical UUID shape
/// `xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx` (hex digits, any case).
pub fn looks_like_id(s: &str) -> bool {
    s.len() == 36
        && s.bytes().enumerate().all(|(i, b)| match i {
            8 | 13 | 18 | 23 => b == b'-',
            _ => b.is_ascii_hexdigit(),
        })
}

macro_rules! define_id {
    ($(#[$doc:meta])* $name:ident) => {
        $(#[$doc])*
        #[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
        pub struct $name(Uuid);

        impl $name {
            /// Generates a fresh random (version 4) ID from the OS CSPRNG.
            pub fn generate() -> Self {
                Self(uuid::Builder::from_random_bytes(random::array::<16>()).into_uuid())
            }

            /// Builds an ID from its 16 raw bytes.
            pub const fn from_bytes(bytes: [u8; 16]) -> Self {
                Self(Uuid::from_bytes(bytes))
            }

            /// The 16 raw bytes, as used in AAD and binary formats.
            pub const fn as_bytes(&self) -> &[u8; 16] {
                self.0.as_bytes()
            }
        }

        impl FromStr for $name {
            type Err = IdParseError;

            /// Parses the canonical hyphenated form only.
            fn from_str(s: &str) -> Result<Self, Self::Err> {
                if !looks_like_id(s) {
                    return Err(IdParseError);
                }
                Uuid::try_parse(s).map(Self).map_err(|_| IdParseError)
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                fmt::Display::fmt(&self.0.hyphenated(), f)
            }
        }

        impl serde::Serialize for $name {
            fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
                serializer.collect_str(self)
            }
        }

        impl<'de> serde::Deserialize<'de> for $name {
            fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
                let text = <std::borrow::Cow<'de, str>>::deserialize(deserializer)?;
                text.parse().map_err(serde::de::Error::custom)
            }
        }

        impl fmt::Debug for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, concat!(stringify!($name), "({})"), self.0.hyphenated())
            }
        }
    };
}

define_id!(
    /// Identifies an account.
    AccountId
);
define_id!(
    /// Identifies a vault (profile: "Personal", "Trabajo").
    VaultId
);
define_id!(
    /// Identifies a project inside a vault.
    ProjectId
);
define_id!(
    /// Identifies an item inside a project.
    ItemId
);
define_id!(
    /// Identifies an attachment of an item.
    AttachmentId
);
define_id!(
    /// Identifies a field inside an item.
    FieldId
);
define_id!(
    /// Identifies a device (a client installation) of an account.
    DeviceId
);
define_id!(
    /// Identifies an agent identity (generated by the agent when it
    /// registers, design §5.1).
    AgentId
);
define_id!(
    /// Identifies an approval request (`ask`, design §5.3).
    ApprovalId
);
define_id!(
    /// Identifies a task request (ADR 0021): a set of items and permissions
    /// an agent asks for at once, approved on one card.
    TaskId
);
define_id!(
    /// Identifies a sandbox of the credential proxy (ADR 0036 §4): chosen
    /// by the proxy when an issuer starts one, and inside its package.
    SandboxId
);
define_id!(
    /// Identifies an assisted password change (ADR 0022 §5): one item's
    /// rotation inside a task, from `rotate.started` to its confirmation
    /// or cancellation. It is the `pending_id` the agent gets back.
    RotationId
);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn display_parse_roundtrip() {
        let id = VaultId::generate();
        let text = id.to_string();
        assert!(looks_like_id(&text));
        assert_eq!(text.parse::<VaultId>(), Ok(id));
        assert_eq!(text.to_uppercase().parse::<VaultId>(), Ok(id));
    }

    #[test]
    fn serde_uses_the_text_form() {
        let id = FieldId::generate();
        let json = serde_json::to_string(&id).unwrap();
        assert_eq!(json, format!("\"{id}\""));
        assert_eq!(serde_json::from_str::<FieldId>(&json).unwrap(), id);
        assert!(serde_json::from_str::<FieldId>("\"nope\"").is_err());
    }

    #[test]
    fn generated_ids_are_v4() {
        let id = ItemId::generate();
        assert_eq!(id.as_bytes()[6] >> 4, 4);
        assert_eq!(id.as_bytes()[8] >> 6, 0b10);
    }

    #[test]
    fn rejects_non_canonical_forms() {
        for bad in [
            "",
            "6f3e2c1a8b7d4e5f9a0b1c2d3e4f5a6b",
            "{6f3e2c1a-8b7d-4e5f-9a0b-1c2d3e4f5a6b}",
            "urn:uuid:6f3e2c1a-8b7d-4e5f-9a0b-1c2d3e4f5a6b",
            "6f3e2c1a-8b7d-4e5f-9a0b-1c2d3e4f5a6g",
            "trabajo",
        ] {
            assert_eq!(bad.parse::<AccountId>(), Err(IdParseError), "{bad}");
        }
    }
}
